          g.save(); g.strokeStyle = C.blue3; g.setLineDash([3, 3]); [-b, b].forEach(v => { g.beginPath(); g.moveTo(X(v), p.y); g.lineTo(X(v), p.y + p.h); g.stroke(); }); g.restore();
