        if (st.view === 'scale' && f9 && f9.params) { const P = f9[st.axis], [sT, sE] = P.series; ro7.innerHTML = `<span>fitted slope: T++ <b>${sT.fit.slope.toFixed(4)}</b>, EBT <b>${sE.fit.slope.toFixed(4)}</b></span><span>ratio − 1 = <b>${((sE.fit.slope / sT.fit.slope - 1) * 100).toFixed(2)}%</b> "faster"</span><span>EBT loss higher at all <b>5</b> sizes (${sE.points.map((p, i) => (p[1] - sT.points[i][1]).toFixed(3)).join(', ')})</span>`; }
